  v('gs', H, [1, 2], 'Natur und Umwelt', 'Frühblüher', 'Sachtext, richtig oder falsch, malen', [st('Lies den Text. Beantworte die Fragen.', 'Frühblüher', 'Frühblüher blühen schon im Frühling, wenn es noch kalt ist.\nDazu gehören Schneeglöckchen, Krokus, Tulpe und Narzisse.\nSie haben im Boden eine Zwiebel oder eine Knolle.\nDort speichern sie im Winter Kraft für das neue Jahr.', 'Wann blühen Frühblüher?|Schon im Frühling, wenn es noch kalt ist.\nWo speichern sie ihre Kraft?|In der Zwiebel oder Knolle im Boden.', { syl: 'boegen' }), tf('Richtig oder falsch?', [['Die Tulpe ist ein Frühblüher.', true], ['Frühblüher blühen im Herbst.', false], ['Der Krokus hat eine Knolle.', true]]), male('Male einen Frühblüher mit Zwiebel.', 60)]);
