  v('gs', H, [3, 4], 'Raum, Mobilität und Verkehr', 'Himmelsrichtungen und Kompass', 'Norden, Osten, Süden, Westen', [st('Lies den Text. Beantworte die Fragen.', 'Die Himmelsrichtungen', 'Es gibt vier Himmelsrichtungen: Norden, Osten, Süden und Westen.\nDie Sonne geht im Osten auf. Mittags steht sie im Süden.\nIm Westen geht sie unter.\nMit einem Kompass findest du die Richtung: Die Nadel zeigt immer nach Norden.', 'Wo geht die Sonne auf?|Im Osten.\nWohin zeigt die Kompassnadel?|Nach Norden.', { lineNums: true }), gapE('Setze ein.', 'Die Sonne geht im [Osten] auf.\nMittags steht die Sonne im [Süden].\nAbends geht sie im [Westen] unter.\nDie Kompassnadel zeigt nach [Norden].'), ['lines', { title: 'Merksatz: Nie ohne Seife waschen. Was bedeuten die Anfangsbuchstaben?', count: 2, answer: 'Norden, Osten, Süden, Westen (im Uhrzeigersinn)' }]]);
  v('gs', H, [3, 4], 'Körper, Gesundheit und Entwicklung', 'Die Ernährungspyramide', 'Ausgewogen essen und trinken', [st('Lies den Text. Beantworte die Fragen.', 'Die Ernährungspyramide', 'Die Ernährungspyramide zeigt, wie viel wir von welchen Lebensmitteln essen sollen.\nUnten stehen Getränke: Wasser und ungesüßter Tee. Davon brauchen wir am meisten.\nDarüber kommen Obst und Gemüse, dann Brot, Nudeln und Kartoffeln.\nWeiter oben stehen Milch, Fleisch, Fisch und Eier.\nGanz oben sind Süßigkeiten. Davon essen wir nur wenig.', 'Wovon brauchen wir am meisten?|Von Getränken wie Wasser.\nWovon sollen wir nur wenig essen?|Von Süßigkeiten.', { lineNums: true }), tab('Was hast du heute gegessen und getrunken?', [['Mahlzeit', 'Essen und Trinken'], ['Frühstück', ''], ['Pause', ''], ['Mittagessen', ''], ['Abendessen', '']], { rowH: 12 })]);
