  v('gs', D, [3, 4], 'Schreiben', 'Einen Bericht schreiben', 'W-Fragen beantworten, sachlich schreiben', [['text', { text: 'Ein **Bericht** informiert sachlich und in der richtigen Reihenfolge. Er beantwortet die **W-Fragen**: Wer? Was? Wann? Wo? Wie? Warum? Er steht im **Präteritum**.', box: true }], ['text', { text: 'Am Dienstag fand Ben in der großen Pause auf dem Schulhof einen Schlüsselbund. Er lag unter der Bank neben dem Klettergerüst. Ben brachte ihn sofort ins Sekretariat. Am Nachmittag holte Herr Yilmaz seine Schlüssel dort ab und bedankte sich.' }], tab('Beantworte die W-Fragen.', [['W-Frage', 'Antwort'], ['Wer?', '[Ben]'], ['Was?', '[Er fand einen Schlüsselbund.]'], ['Wann?', '[am Dienstag in der großen Pause]'], ['Wo?', '[auf dem Schulhof, unter der Bank]'], ['Was geschah danach?', '[Er brachte ihn ins Sekretariat.]']], { rowH: 12 }), lin('Schreibe einen kurzen Bericht über ein Ereignis aus deiner Schule.', 6)]);
  v('gs', D, [3, 4], 'Schreiben', 'Eine Erzählung planen', 'Einleitung, Hauptteil, Schluss', [['text', { text: '**So ist eine Erzählung aufgebaut:** In der **Einleitung** erfährst du, wer, wann und wo. Im **Hauptteil** passiert etwas Spannendes – das ist der Höhepunkt. Im **Schluss** wird das Problem gelöst.', box: true }], tab('Plane deine Geschichte „Ein Tag, an dem alles schiefging“ in Stichpunkten.', [['Teil', 'Stichpunkte'], ['Einleitung: Wer? Wann? Wo?', ''], ['Hauptteil: Was passiert? Höhepunkt', ''], ['Schluss: Wie geht es aus?', '']], { rowH: 22 }), ['text', { text: '**Tipp:** Verwende treffende Verben, wörtliche Rede und Adjektive. Schreibe im Präteritum.' }], lin('Schreibe deine Geschichte.', 8)], { noFill: true });
  v('gs', D, [3, 4], 'Lesen', 'Eine Anleitung lesen: Obstsalat', 'Gebrauchstext verstehen und umsetzen', [st('Lies das Rezept. Beantworte die Fragen.', 'Bunter Obstsalat für vier Kinder', 'Du brauchst: 2 Äpfel, 2 Bananen, 1 Orange, eine Handvoll Weintrauben, den Saft einer halben Zitrone.\n1. Wasche die Äpfel und die Weintrauben.\n2. Schneide die Äpfel in kleine Stücke. Lass dir dabei von einem Erwachsenen helfen.\n3. Schäle die Bananen und die Orange und schneide sie klein.\n4. Gib alles in eine Schüssel und träufle den Zitronensaft darüber.\n5. Rühre vorsichtig um. Guten Appetit!', 'Für wie viele Kinder reicht der Obstsalat?|Für vier Kinder.\nWelche Früchte brauchst du?|Äpfel, Bananen, eine Orange und Weintrauben.\nWozu gibst du Zitronensaft dazu?|Damit das Obst frisch bleibt und nicht braun wird.', { lineNums: true }), ['lines', { title: 'Schreibe ein eigenes Rezept für dein Lieblingsessen.', count: 5 }]]);
  v('gs', D, [3, 4], 'Lesen', 'Tabellen und Schaubilder lesen', 'Informationen aus einer Tabelle entnehmen', [['text', { text: 'Die Klasse 3c hat eine Umfrage gemacht: **Wie kommst du zur Schule?**', box: true }], tab('Ergebnis der Umfrage', [['Weg zur Schule', 'Anzahl der Kinder'], ['zu Fuß', '9'], ['mit dem Fahrrad', '6'], ['mit dem Bus', '5'], ['mit dem Auto', '4']]), gapE('Beantworte die Fragen mit der Tabelle.', 'Die meisten Kinder kommen [zu Fuß].\nMit dem Bus kommen [5] Kinder.\nIn der Klasse sind [24] Kinder.\nMit dem Fahrrad kommen [2] Kinder mehr als mit dem Auto.', { bank: false }), ['chart', { title: 'Zeichne das Säulendiagramm.', kind: 'saeulen', rows: [{ l: 'zu Fuß', r: '9' }, { l: 'Fahrrad', r: '6' }, { l: 'Bus', r: '5' }, { l: 'Auto', r: '4' }], empty: true, h: 55 }]]);

