  v('gs', M, [1, 2], 'Raum und Form', 'Lagebegriffe: links, rechts, oben, unten', 'Sich im Raum orientieren', [['text', { text: 'Male nach der Anleitung. Lies genau!', box: true }], ['space', { title: 'Male in die Mitte einen Tisch. Male einen Ball **unter** den Tisch. Male eine Lampe **über** den Tisch. Male eine Katze **links** neben den Tisch und einen Hund **rechts** neben den Tisch.', style: 'rahmen', height: 125 }], tf('Richtig oder falsch? Schau auf dein Bild.', [['Der Ball liegt unter dem Tisch.', true], ['Die Katze sitzt rechts neben dem Tisch.', false], ['Die Lampe hängt über dem Tisch.', true], ['Der Hund sitzt links neben dem Tisch.', false]])], { noFill: true });
