  v('gs', M, [2, 3], 'Raum und Form', 'Körperformen: Würfel, Quader, Kugel …', 'Körper benennen, Ecken, Kanten und Flächen zählen', [tab('Ergänze die Tabelle. Nimm die Körper dazu in die Hand.', [['Körper', 'Ecken', 'Kanten', 'Flächen'], ['Würfel', '[8]', '[12]', '[6]'], ['Quader', '[8]', '[12]', '[6]'], ['Pyramide (mit viereckiger Grundfläche)', '[5]', '[8]', '[5]'], ['Zylinder', '[0]', '[2]', '[3]'], ['Kugel', '[0]', '[0]', '[1]']], { rowH: 12 }), tf('Richtig oder falsch?', [['Ein Würfel ist ein besonderer Quader.', true], ['Eine Kugel kann rollen.', true], ['Ein Quader hat nur quadratische Flächen.', false], ['Eine Konservendose hat die Form eines Zylinders.', true]]), ['lines', { title: 'Finde Gegenstände im Klassenzimmer. Welche Form haben sie?', count: 3 }]]);
  v('gs', M, [1, 2], 'Zahlen und Operationen', 'Gerade und ungerade Zahlen', 'Zahlbeziehungen erkennen', [['text', { text: '**Merke:** **Gerade** Zahlen kannst du in zwei gleich große Teile teilen: 2, 4, 6, 8, 10 … Sie enden auf 0, 2, 4, 6 oder 8. Alle anderen Zahlen sind **ungerade**.', box: true }], tab('Sortiere die Zahlen: 7, 12, 15, 20, 33, 48, 51, 64, 89, 96', [['gerade', 'ungerade'], ['[12, 20, 48, 64, 96]', '[7, 15, 33, 51, 89]']], { rowH: 16 }), ['sequence', { title: 'Setze die Zahlenfolgen fort.', kind: '+', range: 100, step: 2, count: 4, length: 7, blanks: 3 }]]);
  v('gs', M, [3, 4], 'Größen und Messen', 'Brüche bei Größen: ½, ¼, ¾', 'Halbe, Viertel und Dreiviertel im Alltag', [['text', { text: '**Merke:** ½ kg = 500 g · ¼ kg = 250 g · ¾ kg = 750 g · ½ h = 30 min · ¼ h = 15 min · ¾ h = 45 min · ½ l = 500 ml · ½ m = 50 cm', box: true }], gapE('Ergänze.', '½ kg = [500] g\n¼ kg = [250] g\n¾ kg = [750] g\n½ Stunde = [30] min\n¼ Stunde = [15] min\n¾ Stunde = [45] min\n½ l = [500] ml\n¼ l = [250] ml\n½ m = [50] cm\n¼ m = [25] cm', { bank: false }), ['sachaufgabe', { title: 'Löse die Sachaufgabe.', source: 'eigene', text: 'Für einen Kuchen braucht Mia ½ kg Mehl und ¼ kg Zucker.', frage: true, solF: 'Wie viel Gramm Mehl und Zucker braucht Mia zusammen?', solR: '500 g + 250 g = 750 g', solA: 'Mia braucht zusammen 750 g.' }]]);
  v('gs', M, [3, 4], 'Daten und Zufall', 'Einen Fahrplan lesen', 'Abfahrt, Ankunft, Fahrzeit bestimmen', [tab('Busfahrplan Linie 7', [['Haltestelle', 'Bus A', 'Bus B', 'Bus C'], ['Bahnhof', '7:05', '7:35', '8:05'], ['Rathaus', '7:12', '7:42', '8:12'], ['Schule', '7:20', '7:50', '8:20'], ['Schwimmbad', '7:31', '8:01', '8:31']]), gapE('Beantworte die Fragen mit dem Fahrplan.', 'Bus A fährt am Bahnhof um [7:05] Uhr ab.\nVom Bahnhof bis zur Schule braucht der Bus [15] Minuten.\nWer um 7:45 Uhr am Rathaus ist, nimmt Bus [C].\nBus B kommt um [8:01] Uhr am Schwimmbad an.\nVom Rathaus zum Schwimmbad dauert die Fahrt [19] Minuten.', { bank: false }), ['lines', { title: 'Stelle selbst eine Frage zum Fahrplan und beantworte sie.', count: 2 }]]);
  v('gs', M, [3, 4], 'Daten und Zufall', 'Würfeln und Glücksrad: Was ist wahrscheinlicher?', 'Gewinnchancen schätzen und prüfen', [tab('Du würfelst einmal mit einem normalen Spielwürfel. Kreuze an.', [['Ereignis', 'sicher', 'möglich', 'unmöglich'], ['Ich würfle eine 6.', '', '[X]', ''], ['Ich würfle eine 7.', '', '', '[X]'], ['Ich würfle eine Zahl von 1 bis 6.', '[X]', '', ''], ['Ich würfle eine gerade Zahl.', '', '[X]', '']]), gapE('Was ist wahrscheinlicher? Schreibe das Ereignis auf.', 'Eine 6 oder eine gerade Zahl? → [eine gerade Zahl]\nEine 1 oder eine Zahl größer als 2? → [eine Zahl größer als 2]', { bank: false }), tab('Würfle 30-mal. Mache eine Strichliste.', [['Augenzahl', '1', '2', '3', '4', '5', '6'], ['Striche', '', '', '', '', '', ''], ['Anzahl', '', '', '', '', '', '']], { rowH: 14 })], { noFill: true });
  v('gs', M, [3, 4], 'Zahlen und Operationen', 'Teiler und Vielfache', 'Einmaleins nutzen, Zahlbeziehungen erkennen', [gapE('Schreibe die ersten zehn Vielfachen auf.', 'Vielfache von 4: [4, 8, 12, 16, 20, 24, 28, 32, 36, 40]\nVielfache von 6: [6, 12, 18, 24, 30, 36, 42, 48, 54, 60]', { bank: false }), gapE('Finde alle Teiler.', 'Teiler von 12: [1, 2, 3, 4, 6, 12]\nTeiler von 18: [1, 2, 3, 6, 9, 18]\nTeiler von 20: [1, 2, 4, 5, 10, 20]', { bank: false }), tf('Richtig oder falsch?', [['24 ist ein Vielfaches von 6.', true], ['7 ist ein Teiler von 30.', false], ['Jede Zahl ist durch 1 teilbar.', true], ['36 ist ein Vielfaches von 8.', false]])]);
  v('gs', M, [4], 'Raum und Form', 'Maßstab: Verkleinern und Vergrößern', 'Entfernungen auf Plänen bestimmen', [['text', { text: '**Merke:** Maßstab **1 : 100** bedeutet: 1 cm auf dem Plan sind 100 cm = 1 m in Wirklichkeit.', box: true }], tab('Ergänze. Der Plan hat den Maßstab 1 : 100.', [['auf dem Plan', 'in Wirklichkeit'], ['1 cm', '[1 m]'], ['5 cm', '[5 m]'], ['8 cm', '[8 m]'], ['[3 cm]', '3 m'], ['[12 cm]', '12 m']]), ['space', { title: 'Zeichne dein Zimmer im Maßstab 1 : 100 (1 Kästchen = 50 cm).', style: 'karo', height: 75 }]]);
  v('gs', M, [3, 4], 'Zahlen und Operationen', 'Überschlagen und schätzen', 'Ergebnisse prüfen, Fermi-Fragen', [['packet', { title: 'Überschlage zuerst. Rechne dann genau.', op: '+−', range: 1000, count: 9, cols: 3 }], ['text', { text: '**Knobelfrage:** Wie viele Schritte gehst du ungefähr an einem Schultag? Wie bist du vorgegangen?', box: true }], ['lines', { title: 'Schreibe deine Schätzung und deinen Lösungsweg auf.', count: 4 }]]);

  /* HSU nach LehrplanPLUS (eigene Sachtexte) */
  v('gs', H, [3, 4], 'Demokratie und Gesellschaft', 'Die Gemeinde: Bürgermeister und Gemeinderat', 'Aufgaben der Gemeinde kennen', [st('Lies den Text. Beantworte die Fragen.', 'Wer entscheidet in der Gemeinde?', 'Jede Gemeinde hat eine Bürgermeisterin oder einen Bürgermeister. Sie oder er leitet die Gemeinde.\nDie Bürgerinnen und Bürger wählen außerdem den Gemeinderat, in Städten heißt er Stadtrat.\nDer Gemeinderat entscheidet gemeinsam, zum Beispiel ob ein neuer Spielplatz gebaut wird.\nDie Gemeinde kümmert sich um viele Aufgaben: Schulen, Kindergärten, Straßen, Wasser, Müllabfuhr und die Feuerwehr.\nIm Gemeinderat wird abgestimmt. Was die Mehrheit beschließt, gilt.', 'Wer leitet die Gemeinde?|Die Bürgermeisterin oder der Bürgermeister.\nWer wählt den Gemeinderat?|Die Bürgerinnen und Bürger.\nNenne drei Aufgaben der Gemeinde.|Zum Beispiel Schulen, Straßen, Müllabfuhr, Wasser, Feuerwehr.', { lineNums: true }), ['lines', { title: 'Was würdest du in deiner Gemeinde verändern, wenn du Bürgermeisterin oder Bürgermeister wärst?', count: 3 }]]);
  v('gs', H, [3, 4], 'Demokratie und Gesellschaft', 'Werbung durchschauen', 'Kinder als Kunden, Werbetricks erkennen', [st('Lies den Text. Beantworte die Fragen.', 'Werbung will verkaufen', 'Werbung siehst du überall: im Fernsehen, im Internet, auf Plakaten und auf Verpackungen.\nWerbung soll dich dazu bringen, etwas zu kaufen.\nDazu werden Tricks benutzt: fröhliche Musik, bekannte Figuren, Sammelbilder oder kleine Geschenke.\nIm Supermarkt stehen Süßigkeiten oft auf Augenhöhe von Kindern und direkt an der Kasse.\nFrage dich deshalb immer: Brauche ich das wirklich?', 'Was will Werbung erreichen?|Dass man etwas kauft.\nNenne zwei Werbetricks.|Zum Beispiel fröhliche Musik, bekannte Figuren, Sammelbilder, Geschenke.\nWarum stehen Süßigkeiten an der Kasse?|Weil Kinder dort warten und sie sehen.', { lineNums: true }), ['lines', { title: 'Beschreibe eine Werbung, die du kennst. Welche Tricks benutzt sie?', count: 3 }]]);
  v('gs', H, [3, 4], 'Körper und Gesundheit', 'Das Auge', 'Aufbau des Auges und Schutz', [st('Lies den Text. Beantworte die Fragen.', 'So sehen wir', 'Von außen siehst du das Weiße im Auge, die farbige Regenbogenhaut und das schwarze Loch in der Mitte: die Pupille.\nDurch die Pupille fällt Licht ins Auge. Bei hellem Licht wird sie klein, im Dunkeln wird sie groß.\nHinter der Pupille liegt die Linse. Sie bündelt das Licht.\nAuf der Netzhaut hinten im Auge entsteht ein Bild. Der Sehnerv leitet es zum Gehirn.\nAugenbrauen, Wimpern und Lider schützen das Auge vor Schweiß, Staub und grellem Licht.', 'Wozu dient die Pupille?|Durch sie fällt Licht ins Auge.\nWas passiert mit der Pupille bei hellem Licht?|Sie wird klein.', { lineNums: true }), mat('Verbinde Teil und Aufgabe.', [['die Pupille', 'lässt Licht ins Auge'], ['die Linse', 'bündelt das Licht'], ['die Netzhaut', 'hier entsteht das Bild'], ['der Sehnerv', 'leitet das Bild zum Gehirn'], ['die Wimpern', 'schützen vor Staub']])]);
  v('gs', H, [3, 4], 'Körper und Gesundheit', 'Erste Hilfe und Notruf', 'Bei kleinen Verletzungen helfen, Notruf absetzen', [['text', { text: '**Notruf 112** (Rettungsdienst und Feuerwehr) · **Polizei 110**. Bleib ruhig und beantworte die Fragen am Telefon. Leg erst auf, wenn die Leitstelle es sagt.', box: true }], tab('Was sagst du beim Notruf? Ergänze.', [['Frage', 'Deine Antwort (Beispiel)'], ['Wo ist es passiert?', ''], ['Was ist passiert?', ''], ['Wie viele Verletzte gibt es?', ''], ['Wer ruft an?', '']], { rowH: 12 }), tf('Richtig oder falsch?', [['Eine kleine Schürfwunde decke ich mit einem sauberen Pflaster ab.', true], ['Bei Nasenbluten lege ich den Kopf weit in den Nacken.', false], ['Bei einer Verbrennung kühle ich die Stelle mit lauwarmem, fließendem Wasser.', true], ['Bei einem Notfall hole ich sofort einen Erwachsenen.', true]])]);
  v('gs', H, [3, 4], 'Natur und Umwelt', 'Vom Laich zum Frosch', 'Entwicklung eines Tieres am Gewässer', [st('Lies den Text. Beantworte die Fragen.', 'Die Entwicklung des Frosches', 'Im Frühling legt das Froschweibchen Laich ins Wasser. Das sind viele kleine Eier in einer Gallerte.\nAus den Eiern schlüpfen Kaulquappen. Sie leben im Wasser und atmen mit Kiemen.\nNach einigen Wochen wachsen zuerst die Hinterbeine, dann die Vorderbeine.\nDer Schwanz wird immer kürzer. Die Kaulquappe atmet jetzt mit Lungen.\nAus der Kaulquappe ist ein kleiner Frosch geworden. Er kann an Land gehen.', 'Wo legt das Froschweibchen den Laich ab?|Ins Wasser.\nWomit atmen Kaulquappen?|Mit Kiemen.\nWelche Beine wachsen zuerst?|Die Hinterbeine.', { lineNums: true }), tab('Bringe die Entwicklung in die richtige Reihenfolge. Nummeriere.', [['Nummer', 'Entwicklungsstufe'], ['[3]', 'Kaulquappe mit Hinterbeinen'], ['[1]', 'Froschlaich'], ['[5]', 'junger Frosch'], ['[2]', 'Kaulquappe ohne Beine'], ['[4]', 'Kaulquappe mit vier Beinen und kurzem Schwanz']])]);
  v('gs', H, [3, 4], 'Natur und Umwelt', 'Laubbäume und Nadelbäume', 'Bäume im Wald unterscheiden', [st('Lies den Text. Beantworte die Fragen.', 'Bäume in unserem Wald', 'In unseren Wäldern wachsen Laubbäume und Nadelbäume.\nLaubbäume wie Buche, Eiche und Ahorn haben breite Blätter. Im Herbst verlieren die meisten ihre Blätter.\nNadelbäume wie Fichte, Tanne und Kiefer haben schmale Nadeln. Sie bleiben meist das ganze Jahr grün.\nDie Lärche ist eine Ausnahme: Sie ist ein Nadelbaum, verliert ihre Nadeln aber im Herbst.\nEinen Wald mit Laub- und Nadelbäumen nennt man Mischwald.', 'Nenne drei Laubbäume.|Buche, Eiche, Ahorn.\nWelcher Nadelbaum verliert seine Nadeln im Herbst?|Die Lärche.\nWas ist ein Mischwald?|Ein Wald mit Laub- und Nadelbäumen.', { lineNums: true }), tab('Sortiere: Buche, Fichte, Eiche, Kiefer, Ahorn, Tanne, Birke, Lärche', [['Laubbäume', 'Nadelbäume'], ['[Buche, Eiche, Ahorn, Birke]', '[Fichte, Kiefer, Tanne, Lärche]']], { rowH: 16 })]);
  v('gs', H, [3, 4], 'Natur und Umwelt', 'Vom Korn zum Brot', 'Herkunft von Lebensmitteln', [st('Lies den Text. Beantworte die Fragen.', 'Vom Korn zum Brot', 'Im Herbst sät die Landwirtin Getreide wie Weizen oder Roggen auf das Feld.\nIm Sommer ist das Getreide reif. Der Mähdrescher erntet die Körner.\nIn der Mühle werden die Körner zu Mehl gemahlen.\nDie Bäckerin mischt Mehl, Wasser, Salz und Hefe zu einem Teig.\nDer Teig geht auf und wird im Ofen gebacken. So entsteht Brot.', 'Wann ist das Getreide reif?|Im Sommer.\nWo werden die Körner zu Mehl?|In der Mühle.\nWas kommt in den Brotteig?|Mehl, Wasser, Salz und Hefe.', { lineNums: true }), tab('Bringe in die richtige Reihenfolge. Nummeriere.', [['Nummer', 'Schritt'], ['[3]', 'Die Körner werden zu Mehl gemahlen.'], ['[1]', 'Das Getreide wird gesät.'], ['[5]', 'Das Brot wird gebacken.'], ['[2]', 'Der Mähdrescher erntet die Körner.'], ['[4]', 'Der Teig wird geknetet.']])]);
  v('gs', H, [3, 4], 'Natur und Umwelt', 'Feuer: Verbrennen und Löschen', 'Das Verbrennungsdreieck, richtig löschen', [st('Lies den Text. Beantworte die Fragen.', 'Was ein Feuer braucht', 'Ein Feuer brennt nur, wenn drei Dinge zusammenkommen: ein Brennstoff, Sauerstoff aus der Luft und genug Wärme.\nFehlt eines davon, geht das Feuer aus.\nDeshalb kann man ein Feuer auf drei Arten löschen: Man nimmt den Brennstoff weg, man nimmt den Sauerstoff weg (zum Beispiel mit einer Löschdecke) oder man kühlt es mit Wasser.\nBrennendes Fett darf man nie mit Wasser löschen.', 'Welche drei Dinge braucht ein Feuer?|Brennstoff, Sauerstoff und Wärme.\nWie wirkt eine Löschdecke?|Sie nimmt dem Feuer den Sauerstoff.\nWomit darf man brennendes Fett nicht löschen?|Mit Wasser.', { lineNums: true }), mat('Wie wird das Feuer gelöscht? Verbinde.', [['Deckel auf den Topf legen', 'Sauerstoff fehlt'], ['mit Wasser kühlen', 'Wärme fehlt'], ['Holz aus dem Lagerfeuer nehmen', 'Brennstoff fehlt']])]);
  v('gs', H, [3, 4], 'Technik und Kultur', 'Der Hebel', 'Hebel im Alltag erkennen', [st('Lies den Text. Beantworte die Fragen.', 'Mit dem Hebel geht es leichter', 'Mit einem Hebel kann man schwere Dinge mit wenig Kraft bewegen.\nEin Hebel hat einen Drehpunkt. Je weiter weg vom Drehpunkt du drückst, desto weniger Kraft brauchst du.\nHebel findest du überall: Die Wippe, die Schere, die Zange, der Flaschenöffner und die Schubkarre nutzen den Hebel.', 'Was hat jeder Hebel?|Einen Drehpunkt.\nWo musst du drücken, damit du wenig Kraft brauchst?|Weit weg vom Drehpunkt.\nNenne drei Hebel aus dem Alltag.|Zum Beispiel Wippe, Schere, Zange, Flaschenöffner, Schubkarre.', { lineNums: true }), male('Zeichne eine Wippe. Markiere den Drehpunkt.', 55)]);
  v('gs', H, [3, 4], 'Raum und Mobilität', 'Gemeinde, Landkreis, Bayern, Deutschland, Europa', 'Räume ordnen', [['text', { text: 'Jeder Ort gehört zu größeren Räumen: Die **Gemeinde** liegt in einem **Landkreis**. Der Landkreis gehört zu einem **Regierungsbezirk** in **Bayern**. Bayern ist ein Land der **Bundesrepublik Deutschland**. Deutschland liegt in **Europa**.', box: true }], tab('Wo wohnst du? Ergänze.', [['Raum', 'Name'], ['Gemeinde oder Stadt', ''], ['Landkreis', ''], ['Regierungsbezirk', ''], ['Bundesland', '[Bayern]'], ['Staat', '[Deutschland]'], ['Kontinent', '[Europa]']]), tf('Richtig oder falsch?', [['München ist die Hauptstadt von Bayern.', true], ['Berlin ist die Hauptstadt von Deutschland.', true], ['Bayern hat sieben Regierungsbezirke.', true], ['Österreich ist ein Bundesland von Deutschland.', false]])]);
